            "solution": "<?php\ndeclare(strict_types=1);\n\nnamespace Acme\\Logging\\Consolidated;\n\nabstract class AbstractLogger\n{\n    protected int $minLevel;\n\n    public function __construct(int $minLevel = self::INFO)\n    {\n        $this->minLevel = $minLevel;\n    }\n\n    protected function shouldLog(int $level): bool\n    {\n        return $level >= $this->minLevel;\n    }\n\n    protected function format(int $level, string $message): string\n    {\n        $timestamp = date('Y-m-d H:i:s');\n        $levelName = $this->getLevelName($level);\n        return \"[{$timestamp}] {$levelName}: {$message}\";\n    }\n\n    protected function getLevelName(int $level): string\n    {\n        return match($level) {\n            self::DEBUG => 'DEBUG',\n            self::INFO => 'INFO',\n            self::WARNING => 'WARNING',\n            self::ERROR => 'ERROR',\n            default => 'UNKNOWN',\n        };\n    }\n\n    abstract protected function write(string $formatted): void;\n\n    public function log(int $level, string $message): void\n    {\n        if (!$this->shouldLog($level)) {\n            return;\n        }\n        $this->write($this->format($level, $message));\n    }\n\n    public const DEBUG = 0;\n    public const INFO = 1;\n    public const WARNING = 2;\n    public const ERROR = 3;\n}\n\nclass FileLogger extends AbstractLogger\n{\n    protected string $filepath;\n\n    public function __construct(string $filepath, int $minLevel = self::INFO)\n    {\n